{"intent":"build","plan":"Build a Simon Says game using an Arduino Uno R3, 4 LEDs with resistors, 4 tactile buttons, and a piezo buzzer.","reply":"I have wired the Simon Says game with 4 colored LEDs, 4 buttons, and a piezo buzzer on the Arduino Uno.","more":false,"clearExisting":true,"board":"full","parts":[{"ref":"U1","type":"uno","props":{"code":"const int ledPins[] = {2, 3, 4, 5};
const int btnPins[] = {6, 7, 8, 9};
const int buzzerPin = 10;
int sequence[100];
int gameLen = 0;
int playerPos = 0;
unsigned long lastMillis = 0;
void setup() {
  for(int i=0;i<4;i++) {
    pinMode(ledPins[i], OUTPUT);
    pinMode(btnPins[i], INPUT_PULLUP);
  }
  pinMode(buzzerPin, OUTPUT);
  randomSeed(analogRead(0));
}
void loop() {
  addStep();
  playSequence();
  playerTurn();
}
void addStep() {
  sequence[gameLen++] = random(0, 4);
  delay(500);
}
void playSequence() {
  for(int i=0;i<gameLen;i++) {
    digitalWrite(ledPins[sequence[i]], HIGH);
    tone(buzzerPin, 200 + sequence[i]*100, 300);
    delay(400);
    digitalWrite(ledPins[sequence[i]], LOW);
    delay(200);
  }
}
void playerTurn() {
  for(int i=0;i<gameLen;i++) {
    bool pressed = false;
    while(!pressed) {
      for(int j=0;j<4;j++) {
        if(digitalRead(btnPins[j]) == LOW) {
          digitalWrite(ledPins[j], HIGH);
          tone(buzzerPin, 200 + j*100, 200);
          delay(250);
          digitalWrite(ledPins[j], LOW);
          if(j != sequence[i]) {
            gameOver();
          }
          pressed = true;
          delay(150);
        }
      }
    }
  }
}
void gameOver() {
  for(int i=0;i<3;i++) {
    tone(buzzerPin, 100, 200);
    delay(300);
  }
  gameLen = 0;
