int userStep = 0;
void setup() {
  for(int i=0; i<4; i++) {
    pinMode(leds[i], OUTPUT);
    pinMode(buttons[i], INPUT_PULLUP);
  }
  pinMode(buzzer, OUTPUT);
  randomSeed(analogRead(0));
}
void loop() {
  if(gameLen < 100) {
    sequence[gameLen] = random(0, 4);
    gameLen++;
    playSeq();
    userStep = 0;
  }
  while(userStep < gameLen) {
    int b = readBtn();
    if(b != -1) {
      if(b == sequence[userStep]) {
        flashLed(b, 200);
        userStep++;
      } else {
        gameOver();
        gameLen = 0;
        delay(1000);
        return;
      }
    }
  }
  delay(500);
}
void playSeq() {
  for(int i=0; i<gameLen; i++) {
    flashLed(sequence[i], 400);
    delay(200);
  }
}
void flashLed(int idx, int dur) {
  digitalWrite(leds[idx], HIGH);
  tone(buzzer, 200 + idx*150, dur);
  delay(dur);
  digitalWrite(leds[idx], LOW);
  noTone(buzzer);
}
int readBtn() {
  for(int i=0; i<4; i++) {
    if(digitalRead(buttons[i]) == LOW) {
      delay(50);
      while(digitalRead(buttons[i]) == LOW);
      return i;
    }
  }
  return -1;
}
