    tone(buzzer, 100, 150);
    delay(150);
  }
}"}},{"ref":"V1","type":"vcc"},{"ref":"G1","type":"gnd"},{"ref":"L1","type":"led","props":{"color":"red"}},{"ref":"R1","type":"resistor","props":{"ohms":"220"}},{"ref":"L2","type":"led","props":{"color":"green"}},{"ref":"R2","type":"resistor","props":{"ohms":"220"}},{"ref":"L3","type":"led","props":{"color":"blue"}},{"ref":"R3","type":"resistor","props":{"ohms":"220"}},{"ref":"L4","type":"led","props":{"color":"yellow"}},{"ref":"R4","type":"resistor","props":{"ohms":"220"}},{"ref":"B1","type":"tactile"},{"ref":"B2","type":"tactile"},{"ref":"B3","type":"tactile"},{"ref":"B4","type":"tactile"},{"ref":"BZ1","type":"buzzer"}],"connections":[["V1.5V","+"],["G1.GND","-"],["U1.5V","+"],["U1.GND","-"],["U1.D2","L1.Anode (+)"],["L1.Cathode (−)","R1.1"],["R1.2","-"],["U1.D3","L2.Anode (+)"],["L2.Cathode (−)","R2.1"],["R2.2","-"],["U1.D4","L3.Anode (+)"],["L3.Cathode (−)","R3.1"],["R3.2","-"],["U1.D5","L4.Anode (+)"],["L4.Cathode (−)","R4.1"],["R4.2","-"],["U1.D6","B1.1.l"],["B1.1.r","+"],["B1.2.l","-"],["B1.2.r","-"],["U1.D7","B2.1.l"],["B2.1.r","+"],["B2.2.l","-"],["B2.2.r","-"],["U1.D8","B3.1.l"],["B3.1.r","+"],["B3.2.l","-"],["B3.2.r","-"],["U1.D9","B4.1.l"],["B4.1.r","+"],["B4.2.l","-"],["B4.2.r","-"],["U1.D10","BZ1.+"],["BZ1.−","-"]]}

